#include <vector>

using namespace std;

class Solution {
public:
    vector<int> findPeakGrid(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        int low = 0, high = m - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int maxC = 0;
            for (int c = 1; c < n; ++c) {
                if (mat[mid][c] > mat[mid][maxC]) {
                    maxC = c;
                }
            }

            int topVal = (mid > 0) ? mat[mid - 1][maxC] : -1;
            int botVal = (mid + 1 < m) ? mat[mid + 1][maxC] : -1;

            if (mat[mid][maxC] > topVal && mat[mid][maxC] > botVal) {
                return {mid, maxC};
            } else if (mat[mid][maxC] < topVal) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return {-1, -1};
    }
};

