var findPeakGrid = function(mat) {
    const m = mat.length, n = mat[0].length;
    let low = 0, high = m - 1;

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let maxC = 0;
        for (let c = 1; c < n; ++c) {
            if (mat[mid][c] > mat[mid][maxC]) {
                maxC = c;
            }
        }

        const topVal = mid > 0 ? mat[mid - 1][maxC] : -1;
        const botVal = mid + 1 < m ? mat[mid + 1][maxC] : -1;

        if (mat[mid][maxC] > topVal && mat[mid][maxC] > botVal) {
            return [mid, maxC];
        } else if (mat[mid][maxC] < topVal) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return [-1, -1];
};
